:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --cell-bg: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --highlight: #f5c518;
  --border: #533483;
  --cell-size: clamp(64px, 20vmin, 100px);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  border-radius: 0;
  box-shadow: 8px 8px 0 #0a0a1a;
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
  max-width: 100%;
}

h1 {
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--accent);
  text-align: center;
}

.status {
  font-size: 1.125rem;
  font-weight: 600;
  min-height: 1.5em;
  text-align: center;
}

.board {
  display: grid;
  grid-template-columns: repeat(3, var(--cell-size));
  grid-template-rows: repeat(3, var(--cell-size));
  gap: 4px;
  background: var(--border);
  padding: 4px;
  border: 4px solid var(--border);
}

.cell {
  background: var(--cell-bg);
  border: none;
  font-family: inherit;
  font-size: calc(var(--cell-size) * 0.55);
  font-weight: 700;
  color: var(--text);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.1s, transform 0.05s;
  user-select: none;
  padding: 0;
  line-height: 1;
}

.cell:hover:not(:disabled) {
  background: #1a4a7a;
}

.cell:focus-visible {
  outline: 3px solid var(--highlight);
  outline-offset: -3px;
  z-index: 1;
}

.cell:active:not(:disabled) {
  transform: scale(0.95);
  background: #0a2a4a;
}

.cell:disabled {
  cursor: default;
  opacity: 0.85;
}

.cell.x { color: var(--accent); }
.cell.o { color: #4ecdc4; }

.cell.win {
  background: var(--highlight);
  color: #1a1a2e;
  animation: pulse 0.6s ease-in-out infinite alternate;
}

@keyframes pulse {
  from { box-shadow: inset 0 0 0 0 #f5c518; }
  to { box-shadow: inset 0 0 12px 4px #f5c518; }
}

.restart {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 12px 32px;
  background: var(--accent);
  color: var(--text);
  border: 3px solid var(--border);
  box-shadow: 4px 4px 0 #0a0a1a;
  cursor: pointer;
  transition: transform 0.05s, box-shadow 0.05s, background 0.1s;
}

.restart:hover {
  background: #ff5a75;
}

.restart:focus-visible {
  outline: 3px solid var(--highlight);
  outline-offset: 3px;
}

.restart:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #0a0a1a;
}

@media (max-width: 400px) {
  :root { --cell-size: clamp(56px, 22vmin, 80px); }
  .card { padding: 16px; gap: 16px; }
  h1 { font-size: 1.25rem; }
}

(function () {
  'use strict';

  const boardEl = document.getElementById('board');
  const statusEl = document.getElementById('status');
  const restartBtn = document.getElementById('restart');

  const WIN_LINES = [
    [0,1,2],[3,4,5],[6,7,8],
    [0,3,6],[1,4,7],[2,5,8],
    [0,4,8],[2,4,6]
  ];

  let board = [];
  let currentPlayer = 'X';
  let gameOver = false;
  let cells = [];

  function initBoard() {
    boardEl.innerHTML = '';
    board = Array(9).fill('');
    currentPlayer = 'X';
    gameOver = false;
    cells = [];

    for (let i = 0; i < 9; i++) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'cell';
      btn.dataset.index = i;
      btn.setAttribute('role', 'gridcell');
      btn.setAttribute('aria-label', 'Cell ' + (i + 1) + ', empty');
      btn.addEventListener('click', handleCellClick);
      boardEl.appendChild(btn);
      cells.push(btn);
    }
    updateStatus("Player X's turn");
  }

  function handleCellClick(e) {
    const idx = Number(e.currentTarget.dataset.index);
    if (gameOver || board[idx] !== '') return;

    board[idx] = currentPlayer;
    const cell = cells[idx];
    cell.textContent = currentPlayer;
    cell.classList.add(currentPlayer.toLowerCase());
    cell.disabled = true;
    cell.setAttribute('aria-label', 'Cell ' + (idx + 1) + ', ' + currentPlayer);

    const winLine = checkWin();
    if (winLine) {
      gameOver = true;
      highlightWin(winLine);
      updateStatus('Player ' + currentPlayer + ' wins!');
      disableAllCells();
      return;
    }

    if (board.every(v => v !== '')) {
      gameOver = true;
      updateStatus("It's a draw!");
      disableAllCells();
      return;
    }

    currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
    updateStatus("Player " + currentPlayer + "'s turn");
  }

  function checkWin() {
    for (const line of WIN_LINES) {
      const [a, b, c] = line;
      if (board[a] && board[a] === board[b] && board[a] === board[c]) {
        return line;
      }
    }
    return null;
  }

  function highlightWin(line) {
    line.forEach(i => cells[i].classList.add('win'));
  }

  function disableAllCells() {
    cells.forEach(c => { c.disabled = true; });
  }

  function updateStatus(msg) {
    statusEl.textContent = msg;
  }

  restartBtn.addEventListener('click', initBoard);

  initBoard();
})();
